                <header className="app__toolbar">
                    <Text variant="header-1">Виджет визуализации</Text>
                    <Switch
                        size="m"
                        checked={theme === 'dark'}
                        onUpdate={(checked) => setTheme(checked ? 'dark' : 'light')}
                        content="Тёмная тема"
                    />
                </header>
                <VizWidget datasets={datasets} mode={mode} onModeChange={setMode} height={380} />
            </div>
        </ThemeProvider>
    );
}

