import {chromium} from 'playwright';
import {mkdirSync} from 'node:fs';

const BASE = process.argv[2] ?? 'http://localhost:4173/';
const OUT = '/tmp/pw/shots';
mkdirSync(OUT, {recursive: true});

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1200, height: 700}});

const errors = [];
page.on('console', (msg) => {
    if (msg.type() === 'error' || msg.type() === 'warning') errors.push(`[${msg.type()}] ${msg.text()}`);
});
page.on('pageerror', (err) => errors.push(`[pageerror] ${err.message}`));

const chunks = [];
page.on('request', (req) => {
    const url = req.url();
    if (url.endsWith('.js') && url.includes('/assets/')) chunks.push(url.split('/assets/')[1]);
});

const mark = (label) => chunks.push(`--- ${label}`);

mark('initial load');
await page.goto(BASE, {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-widget__chart svg, .viz-widget__chart canvas', {timeout: 15000});
await page.waitForTimeout(600);
await page.screenshot({path: `${OUT}/1-sales-light.png`});

// hover the chart to show tooltip + crosshair
const chart = await page.locator('.viz-widget__chart').boundingBox();
await page.mouse.move(chart.x + chart.width * 0.55, chart.y + chart.height * 0.5);
await page.waitForTimeout(400);
await page.screenshot({path: `${OUT}/2-sales-light-hover.png`});

mark('click Мониторинг');
await page.getByRole('radio', {name: 'Мониторинг'}).click();
await page.waitForSelector('.viz-widget__chart canvas', {timeout: 15000});
await page.waitForTimeout(800);
await page.screenshot({path: `${OUT}/3-monitoring-light.png`});

const chart2 = await page.locator('.viz-widget__chart').boundingBox();
await page.mouse.move(chart2.x + chart2.width * 0.4, chart2.y + chart2.height * 0.5);
await page.waitForTimeout(400);
await page.screenshot({path: `${OUT}/4-monitoring-light-hover.png`});

mark('toggle dark');
await page.getByText('Тёмная тема').click();
await page.waitForTimeout(800);
await page.screenshot({path: `${OUT}/5-monitoring-dark.png`});

mark('click Продажи (dark)');
await page.getByRole('radio', {name: 'Продажи'}).click();
await page.waitForSelector('.viz-widget__chart svg', {timeout: 15000});
await page.waitForTimeout(600);
await page.screenshot({path: `${OUT}/6-sales-dark.png`});

mark('table view');
await page.getByRole('radio', {name: 'Таблица'}).click();
await page.waitForTimeout(500);
await page.screenshot({path: `${OUT}/7-sales-dark-table.png`});

await page.getByRole('radio', {name: 'Мониторинг'}).click();
await page.waitForTimeout(800);
await page.screenshot({path: `${OUT}/8-monitoring-dark-table.png`});

await page.getByRole('radio', {name: 'График'}).click();
await page.waitForSelector('.viz-widget__chart canvas', {timeout: 15000});
await page.waitForTimeout(600);
await page.screenshot({path: `${OUT}/9-monitoring-dark-back.png`});

console.log('CHUNKS:\n' + chunks.join('\n'));
console.log('ERRORS (' + errors.length + '):\n' + errors.join('\n'));
await browser.close();

