const fs = require('fs');
let p = 'src/viz/format.ts';
let s = fs.readFileSync(p, 'utf8');
s = s.replace("return unit ? `${text} ${unit}` : text;", "return unit ? `${text}\\u00a0${unit}` : text;");
fs.writeFileSync(p, s);

p = 'src/viz/engines/yagrEngine.ts';
s = fs.readFileSync(p, 'utf8');
s = s.replace("import {formatValue} from '../format';", "import {formatTimestamp, formatValue, isDailyTimeline} from '../format';");
s = s.replace("    const precision = dataset.precision ?? 0;\n", "    const precision = dataset.precision ?? 0;\n    const daily = isDailyTimeline(dataset.timeline);\n");
s = s.replace(`                precision,
                sum: false,
                value: (value) => formatValue(value, precision, dataset.unit),`,
`                precision,
                sum: false,
                title: ({x}) => formatTimestamp(x, daily),
                value: (value) => formatValue(value, precision, dataset.unit),`);
s = s.replace(`                y: {
                    label: dataset.unit,
                    splitsCount: 5,
                    precision,
                },`,
`                y: {
                    label: dataset.unit,
                    splitsCount: 5,
                    precision: 'auto',
                },`);
fs.writeFileSync(p, s);

p = 'src/viz/VizWidget.css';
s = fs.readFileSync(p, 'utf8');
s += `
